import java.util.*;public class UI{Scanner s;AdminService a;UI(Scanner s,AdminService a){this.s=s;this.a=a;}void start(){System.out.println("=== SmartStudent Admin Login ===");System.out.print("Username: ");String u=s.nextLine();System.out.print("Password: ");String p=s.nextLine();if(!a.login(u,p)){System.out.println("Access denied.");return;}while(true){System.out.println("\n1 Add  2 View  3 Update  4 Delete  5 Roll Search  6 Name Search  7 Dept Search  8 Marks Search  9 Stats  0 Exit");String c=s.nextLine();switch(c){case"1":add();break;case"2":show(a.dao().all());break;case"3":update();break;case"4":System.out.print("ID: ");System.out.println(a.dao().delete(Integer.parseInt(s.nextLine()))?"Deleted":"Not found");break;case"5":System.out.print("Roll: ");System.out.println(a.dao().byRoll(s.nextLine()));break;case"6":System.out.print("Name: ");show(a.dao().search("name",s.nextLine()));break;case"7":System.out.print("Department: ");show(a.dao().search("department",s.nextLine()));break;case"8":System.out.print("Marks > ");show(a.dao().above(Double.parseDouble(s.nextLine())));break;case"9":a.dao().stats();break;case"0":return;default:System.out.println("Invalid option");}}}void add(){Student x=input();System.out.println(a.dao().add(x)?"Added":"Not added");}void update(){System.out.print("ID: ");int id=Integer.parseInt(s.nextLine());Student x=input();x.setId(id);System.out.println(a.dao().update(x)?"Updated":"Not updated");}Student input(){System.out.print("Name: ");String n=s.nextLine();System.out.print("Roll: ");String r=s.nextLine();System.out.print("Department: ");String d=s.nextLine();String e;do{System.out.print("Email: ");e=s.nextLine();}while(!e.matches("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+$"));String ph;do{System.out.print("Phone (10 digits): ");ph=s.nextLine();}while(!ph.matches("\\d{10}"));double m;do{System.out.print("Marks 0-100: ");m=Double.parseDouble(s.nextLine());}while(m<0||m>100);return new Student(n,r,d,e,ph,m);}void show(List<Student>l){if(l.isEmpty())System.out.println("No records.");else for(Student x:l)System.out.println(x);}}
